359:         // add sort info
360:         if (sorters != null) {
361:             for (Order sortInfo : sorters) {
362:                 criteria.addOrder(sortInfo);
363:             }
364:         }
365: 
366:         return new PagingResult<E>(criteria.list(), getTotalCount(criterion));
