453:     /**
454:      * Helper method: Creates a criteria for the {@link #entityClass} of this dao.
455:      * The query results will be handled with a
456:      * {@link DistinctRootEntityResultTransformer}. The criteria will contain
457:      * all passed criterions.
458:      *
459:      * @return
460:      */
461:     protected Criteria createDistinctRootEntityCriteria(Criterion... criterion) {
462:         Criteria criteria = getSession().createCriteria(entityClass);
463:         addCriterionsToCriteria(criteria, criterion);
464:         criteria.setResultTransformer(Criteria.DISTINCT_ROOT_ENTITY);
465:         criteria.setCacheable(this.useQueryCache);
466:         return criteria;
467:     }
