125:      * @param singular
126:      * @return
127:      */
128:     @SuppressFBWarnings("DM_CONVERT_CASE")
129:     private String transformToPluralForm(String singular) {
130:         String lowercaseSingular = singular.toLowerCase();
131:         if (IRREGULAR_NOUNS.containsKey(lowercaseSingular)) {
132:             // e.g. "Woman" -> "Women", "Ox" -> "Oxen" …
133:             String plural = IRREGULAR_NOUNS.get(lowercaseSingular);
134:             if (Character.isUpperCase(singular.charAt(0)) && plural.length() >= 2) {
135:                 plural = String.valueOf(plural.charAt(0)).toUpperCase() + plural.substring(1);
136:             }
137:             return plural;
138:         }
139: 
140:         StringBuilder plural = new StringBuilder();
141: 
142:         // start with singular form
143:         plural.append(singular);
144: 
145:         if (singular.endsWith(String.valueOf(LAST_CHAR_Y))) {
146:             // e.g. "City" -> "Cities"
147: 
148:             // replace last char with suffix form
149:             int length = plural.length();
150:             plural.replace(length - 1, length, PLURAL_SUFFIX_IES);
151: 
152:         } else if (singular.endsWith(String.valueOf(LAST_CHAR_S))
153:             || singular.endsWith(String.valueOf(LAST_CHAR_X))
154:             || singular.endsWith(String.valueOf(LAST_CHAR_Z))
155:             || singular.endsWith(LAST_CHARS_CH)
156:             || singular.endsWith(LAST_CHARS_SH)) {
157:             // e.g. "Bus" -> "Buses"
158:             // e.g. "Box" -> "Boxes"
159:             // e.g. "Buzz" -> "Buzzes"
160:             // e.g. "Wish" -> "Wishes"
161:             // e.g. "Pitch" -> "Pitches"
162: 
163:             plural.append(PLURAL_SUFFIX_ES);
164: 
165:         } else {
166:             // e.g. "Boat" -> "Boats"
167: 
168:             // default
169:             plural.append(PLURAL_SUFFIX_S);
170:         }
