674:      * @param useWmsReflector
675:      * @param isWMS
676:      * @throws URISyntaxException
677:      * @throws InterceptorException
678:      */
679:     public URI getGeoServerBaseURIFromNameSpace(String geoServerNamespace, boolean useWmsReflector, boolean isWMS)
680:         throws URISyntaxException, InterceptorException {
681: 
682:         URI uri = null;
683: 
684:         String geoServerUrl;
685:         if (namespaceBoundUrl) {
686:             geoServerUrl = this.geoServerNameSpaces.getProperty(
687:                 geoServerNamespace);
688:         } else {
689:             geoServerUrl = defaultOwsUrl;
690:             LOG.debug("Using GeoServer OWS URL without namespace: {}" , geoServerUrl);
691:         }
692: 
693:         if (StringUtils.isEmpty(geoServerUrl)) {
694:             throw new InterceptorException("Couldn't detect GeoServer URI " +
695:                 "from the given namespace");
696:         }
697: 
698:         if (useWmsReflector && isWMS) {
699:             LOG.trace("Will use WMS reflector endpoint");
700:             if (StringUtils.endsWithIgnoreCase(geoServerUrl, "ows")) {
701:                 StringBuilder builder = new StringBuilder();
702:                 int start = geoServerUrl.lastIndexOf("ows");
703:                 builder.append(geoServerUrl, 0, start);
704:                 builder.append("wms" + WMS_REFLECT_ENDPOINT);
705:                 geoServerUrl = builder.toString();
706:             } else if (StringUtils.endsWithIgnoreCase(geoServerUrl, "wms")) {
707:                 geoServerUrl += WMS_REFLECT_ENDPOINT;
708:             }
709:             LOG.trace("The modified endpoint is: " + geoServerUrl);
710:         }
711: 
712:         URIBuilder builder = new URIBuilder(geoServerUrl);
713: 
714:         uri = builder.build();
715: 
716:         return uri;
717:     }
