168:     public static Response sendRequest(MutableHttpServletRequest request)
169:         throws InterceptorException, HttpException {
170: 
171:         Response httpResponse = new Response();
172: 
173:         String requestMethod = request.getMethod();
174:         boolean getRequest = "GET".equalsIgnoreCase(requestMethod);
175:         boolean postRequest = "POST".equalsIgnoreCase(requestMethod);
176: 
177:         try {
178: 
179:             // get the request URI
180:             URI requestUri = new URI(request.getRequestURI());
181: 
182:             Header[] requestHeaders = getRequestHeadersToForward(request);
183: 
184:             // get the query parameters provided by the GET/POST request and
185:             // convert to a list of NameValuePairs
186:             List<NameValuePair> allQueryParams = createQueryParams(request.getParameterMap());
187: 
188:             // append the given request parameters to the base URI
189:             URI fullRequestUri = getFullRequestURI(requestUri, allQueryParams);
190: 
191:             if (getRequest) {
192:                 // if we're called via GET method
193: 
194:                 // perform the request with the given parameters
195:                 httpResponse = HttpUtil.get(fullRequestUri, requestHeaders);
196: 
197:             } else if (postRequest) {
198:                 // if we're called via POST method
199: 
200:                 // We have to attach the actual query; a POST to e.g. http://example.com/?foo=bar is totally OK
201:                 String queryString = request.getQueryString();
202:                 if (queryString != null) {
203:                     requestUri = appendQueryString(requestUri, queryString);
204:                 }
205: 
206:                 // get the request body if any
207:                 String body = OgcXmlUtil.getRequestBody(request);
208: 
209:                 if (!StringUtils.isEmpty(body)) {
210:                     // we do have a POST with string data present
211: 
212:                     // parse the content type of the request
213:                     ContentType contentType = ContentType.parse(request.getContentType());
214: 
215:                     if (contentType.getCharset() == null) {
216:                         // use UTF-8 charset if charset could not be parsed from the content type
217:                         // of the request
218:                         contentType = contentType.withCharset("UTF-8");
219:                     }
220: 
221:                     // perform the POST request to the URI with queryString and with the given body
222:                     httpResponse = HttpUtil.post(requestUri, body, contentType, requestHeaders);
223:                 } else {
224: 
225:                     // perform the POST request with the given name value pairs,
226:                     httpResponse = HttpUtil.post(requestUri, allQueryParams, requestHeaders);
227:                 }
228: 
229:             } else {
230:                 // otherwise throw an exception
231:                 throw new InterceptorException("Only GET or POST method is allowed");
232:             }
