259:      * http://stackoverflow.com/a/26177982.
260:      *
261:      * @param uri
262:      * @param appendQuery
263:      */
264:     public static URI appendQueryString(URI uri, String appendQuery) {
265:         if (uri == null || appendQuery == null || appendQuery.isEmpty()) {
266:             return uri;
267:         }
268:         String newQuery = uri.getQuery();
269:         if (newQuery == null) {
270:             newQuery = appendQuery;
271:         } else {
272:             newQuery += "&" + appendQuery;
273:         }
274:         // Fallback is the old URI
275:         URI newUri = uri;
276:         try {
277:             newUri = new URI(uri.getScheme(), uri.getAuthority(), uri.getPath(), newQuery, uri.getFragment());
278:         } catch (URISyntaxException e) {
279:             String msg = String.format(
280:                 "Failed to append query '%s' to URI '%s', returning URI unchanged.",
281:                 appendQuery, uri
282:             );
283:             LOG.warn(msg);
284:         }
285:         return newUri;
286:     }
