292:     private static HttpHeaders getResponseHeadersToForward(HttpHeaders headers)
293:         throws UnsupportedEncodingException {
294: 
295:         HttpHeaders responseHeaders = new HttpHeaders();
296: 
297:         if (headers == null) {
298:             LOG.debug("No headers found to forward!");
299:             return responseHeaders;
300:         }
301: 
302:         LOG.trace("Requested to filter the Headers to respond with:");
303: 
304:         for (Entry<String, List<String>> header : headers.entrySet()) {
305:             String headerKey = header.getKey();
306:             String headerVal = StringUtils.join(header.getValue(), ",");
307: 
308:             LOG.trace("  * Header: " + headerKey);
309: 
310:             if (Arrays.asList(FORWARD_RESPONSE_HEADER_KEYS).contains(headerKey)) {
311: 
312:                 // the GeoServer response may contain a subtype in the
313:                 // "Content-Type" header without double quotes surrounding the
314:                 // subtype's value. If this is set we need to surround it
315:                 // with double quotes as this is required by the Spring
316:                 // ResponseEntity (and the RFC 2616 standard).
317:                 Pattern pattern = Pattern.compile("subtype=(.*)");
318:                 Matcher matcher = pattern.matcher(headerVal);
319: 
320:                 if (matcher.find()) {
321:                     String replaceCandidate = matcher.group(1);
322:                     String replacer;
323: 
324:                     replacer = StringUtils.prependIfMissing(
325:                         replaceCandidate, "\"");
326:                     replacer = StringUtils.appendIfMissing(
327:                         replacer, "\"");
328: 
329:                     headerVal = StringUtils.replace(headerVal,
330:                         replaceCandidate, replacer);
331:                 }
332: 
333:                 responseHeaders.set(headerKey, headerVal);
334:                 LOG.trace("    > Forwarded");
335:             } else {
336:                 LOG.trace("    > Skipped");
337:             }
338:         }
339: 
340:         return responseHeaders;
341:     }
