343:     @Transactional
344:     public Response interceptWmtsRequest(HttpServletRequest request, String serviceId) throws UnsupportedEncodingException, InterceptorException, HttpException, URISyntaxException {
345:         Matcher matcher = WMTS_PATTERN.matcher(request.getRequestURI());
346:         int id = Integer.parseInt(serviceId);
347:         if (!matcher.matches()) {
348:             throw new InterceptorException("No WMTS request path found!");
349:         }
350:         String path = matcher.group(1);
351: 
352:         // get all layers allowed for this user in order to filter out not allowed ones
353:         List<Layer> layers = layerService.findAll();
354:         WmtsLayerDataSource dataSource = null;
355:         for (Layer layer : layers) {
356:             if (layer.getSource() instanceof WmtsLayerDataSource) {
357:                 WmtsLayerDataSource source = (WmtsLayerDataSource) layer.getSource();
358:                 if (source.getId().equals(id)) {
359:                     dataSource = source;
360:                     break;
361:                 }
362:             }
363:         }
364: 
365:         if (dataSource == null) {
366:             return new Response(HttpStatus.FORBIDDEN, null, new byte[0]);
367:         }
368: 
369:         String baseUrl = dataSource.getUrl();
370:         Response response = HttpUtil.get(baseUrl + "/" + path);
371: 
372:         HttpHeaders forwardingHeaders = getResponseHeadersToForward(response.getHeaders());
373:         response.setHeaders(forwardingHeaders);
374: 
375:         return response;
376:     }
