384:      * @throws IOException
385:      */
386:     public Response interceptGeoServerRequest( HttpServletRequest request )
387:         throws InterceptorException, URISyntaxException,
388:         HttpException, IOException {
389:         return interceptGeoServerRequest( request, Optional.empty() );
