392:     /**
393:      *
394:      * @param request
395:      * @param endpoint
396:      * @return
397:      * @throws InterceptorException
398:      * @throws URISyntaxException
399:      * @throws HttpException
400:      * @throws IOException
401:      */
402:     public Response interceptGeoServerRequest(HttpServletRequest request, Optional<String> endpoint)
403:         throws InterceptorException, URISyntaxException, HttpException, IOException {
404: 
405:         // wrap the request, we want to manipulate it
406:         MutableHttpServletRequest mutableRequest = new MutableHttpServletRequest(request);
407:         if (endpoint.isPresent()) {
408:             mutableRequest.addParameter("CUSTOM_ENDPOINT", endpoint.get());
409:             mutableRequest.addParameter("CONTEXT_PATH", request.getContextPath());
410:         }
411: 
412:         // get the OGC message information (service, request, endPoint)
413:         OgcMessage message = getOgcMessage(mutableRequest);
414: 
415:         // check whether WMS reflector endpoint should be called
416:         final boolean useWmsReflector = shouldReflectEndpointBeCalled(mutableRequest, message);
417: 
418:         // get the GeoServer base URI by the provided request
419:         URI geoServerBaseUri = getGeoServerBaseURI(message, useWmsReflector);
420:         // set the GeoServer base URI to the (wrapped) request
421:         mutableRequest.setRequestURI(geoServerBaseUri);
422: 
423:         // intercept the request (if needed)
424:         mutableRequest = ogcMessageDistributor.distributeToRequestInterceptor(mutableRequest, message);
425: 
426:         // send the request
427:         // TODO: Move to global proxy class
428:         Response response = sendRequest(mutableRequest);
429: 
430:         // intercept the response (if needed)
431:         Response interceptedResponse = ogcMessageDistributor
432:             .distributeToResponseInterceptor(mutableRequest, response, message);
433: 
434:         // finally filter the white-listed response headers
435:         // TODO: Move to global proxy class
436:         HttpHeaders forwardingHeaders = getResponseHeadersToForward(
437:             interceptedResponse.getHeaders()
438:         );
439:         interceptedResponse.setHeaders(forwardingHeaders);
440: 
441:         return interceptedResponse;
442:     }
