444:     /**
445:      * Detect whether the WMS reflector endpoint of GeoServer should be called instead of the one defined in provided message
446:      *
447:      * @param mutableRequest request to check
448:      * @param message        instance of {@link OgcMessage}
449:      * @return true if useReflect found in parameters, false otherwise
450:      * @throws InterceptorException
451:      * @throws IOException
452:      */
453:     private boolean shouldReflectEndpointBeCalled(MutableHttpServletRequest mutableRequest, OgcMessage message) throws InterceptorException, IOException {
454:         boolean useReflect = false;
455: 
456:         if (message.getService() != ServiceType.WMS) {
457:             return useReflect;
458:         }
459: 
460:         String value = MutableHttpServletRequest.getRequestParameterValue(mutableRequest, USE_REFLECT_PARAM);
461:         useReflect = Boolean.valueOf(value);
462:         if (useReflect) {
463:             LOG.info("Parameter " + USE_REFLECT_PARAM + "found in request. Will use WMS reflector endpoint of GeoServer.");
464:         }
465: 
466:         return useReflect;
467:     }
