578:     /**
579:      * @param requestService
580:      * @param requestOperation
581:      * @param requestEndPoint
582:      * @param ruleEvent
583:      * @return
584:      * @throws InterceptorException
585:      */
586:     private InterceptorRule getMostSpecificRule(String requestService,
587:                                                 String requestOperation, String requestEndPoint,
588:                                                 String ruleEvent) throws InterceptorException {
589: 
590:         final ServiceType service = OgcEnum.ServiceType.fromString(
591:             requestService);
592:         final OperationType operation = OgcEnum.OperationType.fromString(
593:             requestOperation);
594:         final String endPoint = requestEndPoint;
595: 
596:         LOG.trace("Finding the most specific interceptor rule for: \n" +
597:             "  * Event: " + ruleEvent + "\n" +
598:             "  * Service: " + service + "\n" +
599:             "  * Operation: " + operation + "\n" +
600:             "  * EndPoint: " + endPoint
601:         );
602: 
603:         // get all persisted rules for the given service and event
604:         List<InterceptorRule> interceptorRules = this.interceptorRuleService
605:             .findAllRulesForServiceAndEvent(requestService, ruleEvent);
606: 
607:         LOG.trace("Got " + interceptorRules.size() + " rule(s) from database.");
608: 
609:         if (LOG.isTraceEnabled()) {
610:             for (InterceptorRule interceptorRule : interceptorRules) {
611:                 LOG.trace("Returned rule is: " + interceptorRule);
612:             }
613:         }
614: 
615:         LOG.trace("Evaluating the given rules for the most specific one:");
616: 
617:         // create the predicate for finding the most specific rule out of
618:         // the given rules (conditions in descending specific order).
619:         // note: we don't need to check for request event (request/response)
620:         // and the service type at all as the rule candidates are filtered by
621:         // the DAO method already. the last check for service specificity found
622:         // here is a fallback only.
623:         HashMap<InterceptorRule, Integer> ruleMap = new HashMap<>();
624:         interceptorRules.stream().forEach((rule) -> {
625:             int score = 0;
626: 
627:             if (!StringUtils.isEmpty(rule.getEndPoint()) && !StringUtils.isEmpty(endPoint) && !StringUtils.equalsIgnoreCase(rule.getEndPoint(), endPoint)) {
628:                 return;
629:             }
630:             if (rule.getService() != null && !Objects.equals(rule.getService(), service) && service != null) {
631:                 return;
632:             }
633:             if (rule.getOperation() != null && !Objects.equals(rule.getOperation(), operation) && operation != null) {
634:                 return;
635:             }
636:             if (endPoint != null && Objects.equals(rule.getEndPoint(), endPoint)) {
637:                 ++score;
638:             }
639:             if (operation != null && Objects.equals(rule.getOperation(), operation)) {
640:                 ++score;
641:             }
642:             if (service != null && Objects.equals(rule.getService(), service)) {
643:                 ++score;
644:             }
645:             ruleMap.put(rule, score);
646:         });
647: 
648:         AtomicReference<Integer> biggestScore = new AtomicReference<>(0);
649:         AtomicReference<InterceptorRule> mostSpecific = new AtomicReference<>();
650: 
651:         ruleMap.entrySet().stream().forEach((entry) -> {
652:             if (entry.getValue() > biggestScore.get()) {
653:                 mostSpecific.set(entry.getKey());
654:                 biggestScore.set(entry.getValue());
655:             }
656:         });
657: 
658:         if (interceptorRules.size() == 0) {
659:             LOG.error("Got no interceptor rules for this request/response. " +
660:                 "Usually this should not happen as one has to define at " +
661:                 "least the basic sets of rules (e.g. ALLOW all WMS " +
662:                 "requests) when using the interceptor.");
663:             throw new InterceptorException("No interceptor rule found.");
664:         } else if (LOG.isTraceEnabled()) {
665:             LOG.trace("Identified the following rule as most the specific " +
666:                 "one: " + mostSpecific.get());
667:         }
668: 
669:         return mostSpecific.get();
670:     }
