231:      * the entity model, but the keys/fieldnames in the input may be
232:      * case-insensitive.
233:      * <p>
234:      * The value for each key is a list of casted (!) values of the string
235:      * values of the given input map. The type of the field in the entity is
236:      * used to determine the correct casting.
237:      *
238:      * @param requestedFilter
239:      * @param entityClass
240:      * @return
241:      */
242:     public static MultiValueMap<String, Object> validFieldNamesWithCastedValues(MultiValueMap<String, String> requestedFilter, Class<?> entityClass) {
243: 
244:         Set<String> inputFieldNames = requestedFilter.keySet();
245: 
246:         // Regarding case insensitivity: build a map that maps from the input field name to its original field name,
247:         // but add only those fields to the map that exist in the entity
248:         Map<String, String> validInputFieldNameToOrigFieldName = new HashMap<>();
249: 
250:         List<String> filterableFieldNames = getFilterableOrRestrictableFieldNames(entityClass);
251:         for (String filterableFieldName : filterableFieldNames) {
252:             // find the corresponding field in the input
253:             for (String inputFieldName : inputFieldNames) {
254:                 if (filterableFieldName.equalsIgnoreCase(inputFieldName)) {
255:                     validInputFieldNameToOrigFieldName.put(inputFieldName, filterableFieldName);
256:                     break;
257:                 }
258:             }
259:         }
260: 
261:         MultiValueMap<String, Object> result = new LinkedMultiValueMap<>();
262: 
263:         for (Map.Entry<String, String> entry : validInputFieldNameToOrigFieldName.entrySet()) {
264:             String validInputFieldName = entry.getKey();
265:             String origInputFieldName = entry.getValue();
266: 
267:             List<String> stringValues = requestedFilter.get(validInputFieldName);
268: 
269:             // cast to the correct type to avoid hibernate exceptions when querying db or similar
270:             for (String fieldStringValue : stringValues) {
271:                 Field f = FieldUtils.getField(entityClass, origInputFieldName, true);
272:                 Class<?> fieldType = f.getType();
273:                 Object castedValue = ConvertUtils.convert(fieldStringValue, fieldType);
274:                 result.add(origInputFieldName, castedValue);
275:             }
276:         }
277: 
278:         return result;
279:     }
280: }

