package de.terrestris.shoguncore.dao;

import jakarta.persistence.criteria.CriteriaBuilder;
import jakarta.persistence.criteria.CriteriaQuery;
import jakarta.persistence.criteria.Predicate;
import jakarta.persistence.criteria.Root;

/**
 * One restriction of a DAO query, built with the JPA Criteria API.
 * <p>
 * A restriction corresponds to a single {@link Predicate} of a criteria
 * query. Multiple restrictions passed to the DAO methods are combined
 * with a logical AND.
 * <p>
 * This type replaces the legacy {@code org.hibernate.criterion.Criterion}
 * API that was removed in Hibernate ORM 6.
 *
 * @param <E> The entity type the restriction applies to
 */
@FunctionalInterface
public interface QueryRestriction<E> {

    /**
     * Builds the {@link Predicate} of this restriction.
     *
     * @param root The root of the criteria query, refering to the queried
     *             entity
     * @param query The criteria query the restriction is part of
     * @param cb The criteria builder to create the predicate with
     * @return The predicate representing this restriction. May be
     *         {@code null}, in which case the restriction is ignored.
     */
    Predicate toPredicate(Root<E> root, CriteriaQuery<?> query, CriteriaBuilder cb);
}

