package de.terrestris.shoguncore.dao;

import de.terrestris.shoguncore.model.interceptor.InterceptorRule;
import de.terrestris.shoguncore.util.enumeration.HttpEnum;
import de.terrestris.shoguncore.util.enumeration.OgcEnum;
import org.springframework.stereotype.Repository;

import java.util.Arrays;
import java.util.List;

/**
 * @param <E>
 * @author Daniel Koch
 * @author Kai Volland
 * @author terrestris GmbH & Co. KG
 */
@Repository("interceptorRuleDao")
public class InterceptorRuleDao<E extends InterceptorRule>
    extends GenericHibernateDao<E, Integer> {

    /**
     * Public default constructor for this DAO.
     */
    @SuppressWarnings("unchecked")
    public InterceptorRuleDao() {
        super((Class<E>) InterceptorRule.class);
    }

    /**
     * Constructor that has to be called by subclasses.
     *
     * @param clazz
     */
    protected InterceptorRuleDao(Class<E> clazz) {
        super(clazz);
    }

    /**
     * @param service
     * @param event
     * @return
     */
    public List<E> findAllRulesForServiceAndEvent(String service, String event) {

        QueryRestriction<E> serviceEquals =
            (root, query, cb) -> cb.equal(root.get("service"),
                OgcEnum.ServiceType.fromString(service));
        QueryRestriction<E> eventEquals =
            (root, query, cb) -> cb.equal(root.get("event"),
                HttpEnum.EventType.fromString(event));

        // order descending by endPoint and operation, so the more specific
        // rules will be listed first (this could make the following evaluation
        // easier)
        List<SortOrder> sorters = Arrays.asList(
            SortOrder.desc("endPoint"),
            SortOrder.desc("operation")
        );

        return findByCriteriaWithSorting(sorters, serviceEquals, eventEquals);
    }

}

