/**
 * Builds a single restriction out of the passed map of fieldnames to
 * casted values: multiple values for one fieldname are combined with a
 * logical OR, the different fieldnames are combined with a logical AND.
 *
 * @param origFieldNamesToCastedValues The map of fieldnames to casted values
 * @return The restriction representing the filter
 */
private QueryRestriction<E> buildSimpleFilterRestriction(MultiValueMap<String, Object> origFieldNamesToCastedValues) {
    return (root, query, cb) -> {
        List<Predicate> fieldPredicates = new ArrayList<Predicate>();

        for (Map.Entry<String, List<Object>> entry : origFieldNamesToCastedValues.entrySet()) {
            // if there are multiple values for a field name, we'll check
            // for equality and connect them with OR
            List<Predicate> eqPredicates = new ArrayList<Predicate>();
            List<Object> fieldValues = entry.getValue();

            for (Object fieldValue : fieldValues) {
                eqPredicates.add(cb.equal(root.get(entry.getKey()), fieldValue));
            }

            if (!eqPredicates.isEmpty()) {
                fieldPredicates.add(cb.or(eqPredicates.toArray(new Predicate[0])));
            }
        }

        if (fieldPredicates.isEmpty()) {
            return cb.conjunction();
        }
        return cb.and(fieldPredicates.toArray(new Predicate[0]));
    };
}

