package de.terrestris.shoguncore.hibernate;

import org.hibernate.HibernateException;
import org.hibernate.engine.spi.SharedSessionContractImplementor;
import org.hibernate.usertype.UserType;
import org.joda.time.DateTime;
import org.joda.time.ReadableDateTime;

import java.io.Serializable;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.sql.Types;
import java.util.Objects;

/**
 * Hibernate {@link UserType} that persists joda-time {@link DateTime}
 * respectively {@link ReadableDateTime} values as SQL timestamps.
 * <p>
 * This replaces the removed jadira usertype
 * {@code org.jadira.usertype.dateandtime.joda.PersistentDateTime} that was
 * used in Hibernate 5.
 */
public class JodaDateTimeUserType implements UserType<ReadableDateTime> {

    /**
     * @return The SQL type of the columns this type is mapped to
     */
    @Override
    public int getSqlType() {
        return Types.TIMESTAMP;
    }

    /**
     * @return The java class this type maps
     */
    @Override
    public Class<ReadableDateTime> returnedClass() {
        return ReadableDateTime.class;
    }

    /**
     * @param x One value to compare
     * @param y The other value to compare
     * @return Whether both values are equal
     */
    @Override
    public boolean equals(ReadableDateTime x, ReadableDateTime y) throws HibernateException {
        return Objects.equals(x, y);
    }

    /**
     * @param x The value to get the hash code of
     * @return The hash code of the value
     */
    @Override
    public int hashCode(ReadableDateTime x) throws HibernateException {
        return x == null ? 0 : x.hashCode();
    }

    /**
     * Reads the value from the given position of the result set.
     *
     * @param rs The result set to read from
     * @param position The position to read from
     * @param session The session
     * @param owner The owner of the value
     * @return The read value or null
     * @throws SQLException If reading from the result set fails
     */
    @Override
    public ReadableDateTime nullSafeGet(ResultSet rs, int position,
                                        SharedSessionContractImplementor session, Object owner)
        throws SQLException {
        final Timestamp timestamp = rs.getTimestamp(position);
        if (rs.wasNull() || timestamp == null) {
            return null;
        }
        return new DateTime(timestamp.getTime());
    }

    /**
     * Writes the value to the given position of the statement.
     *
     * @param st The statement to write to
     * @param value The value to write
     * @param index The position to write to
     * @param session The session
     * @throws SQLException If writing to the statement fails
     */
    @Override
    public void nullSafeSet(PreparedStatement st, ReadableDateTime value, int index,
                            SharedSessionContractImplementor session) throws SQLException {
        if (value == null) {
            st.setNull(index, Types.TIMESTAMP);
        } else {
            st.setTimestamp(index, new Timestamp(value.getMillis()));
        }
    }

    /**
     * @param value The value to copy
     * @return The value itself, as joda-time date values are immutable
     */
    @Override
    public ReadableDateTime deepCopy(ReadableDateTime value) throws HibernateException {
        return value;
    }

    /**
     * @return Whether the mapped type is mutable
     */
    @Override
    public boolean isMutable() {
        return false;
    }

    /**
     * @param value The value to disassemble
     * @return A serializable representation of the value
     */
    @Override
    public Serializable disassemble(ReadableDateTime value) throws HibernateException {
        return value == null ? null : value.getMillis();
    }

    /**
     * @param cached The serializable representation of the value
     * @param owner The owner of the value
     * @return The assembled value
     */
    @Override
    public ReadableDateTime assemble(Serializable cached, Object owner) throws HibernateException {
        return cached == null ? null : new DateTime((Long) cached);
    }
}

