package de.terrestris.shoguncore.hibernate;

import com.fasterxml.jackson.core.JsonProcessingException;
import de.terrestris.shoguncore.util.json.ShogunCoreJsonObjectMapper;
import org.hibernate.HibernateException;
import org.hibernate.engine.spi.SharedSessionContractImplementor;
import org.hibernate.usertype.UserType;

import java.io.IOException;
import java.io.Serializable;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Types;
import java.util.HashMap;
import java.util.Objects;


/**
 * Generic jsonb user type. Annotate your entities with Map&lt;String, Object&gt; as the type.
 */
public class JsonbUserType implements UserType<HashMap> {

    @Override
    public HashMap assemble(Serializable cached, Object owner) throws HibernateException {
        return deepCopy(cached);
    }

    @Override
    public HashMap deepCopy(Object value) throws HibernateException {
        if (value == null) {
            return null;
        }
        ShogunCoreJsonObjectMapper mapper = new ShogunCoreJsonObjectMapper();
        if (value instanceof String) {
            try {
                return mapper.readValue(value.toString(), HashMap.class);
            } catch (IOException e) {
                throw new HibernateException(e);
            }
        }
        try {
            return mapper.readValue(mapper.writeValueAsString(value), HashMap.class);
        } catch (IOException e) {
            throw new HibernateException(e);
        }
    }

    @Override
    public Serializable disassemble(HashMap value) throws HibernateException {
        return this.deepCopy(value);
    }

    @Override
    public boolean isMutable() {
        return true;
    }

    @Override
    public HashMap replace(Object original, Object target, Object owner) throws HibernateException {
        return deepCopy(original);
    }

    @Override
    public Class<HashMap> returnedClass() {
        return HashMap.class;
    }

    @Override
    public boolean equals(HashMap x, HashMap y) throws HibernateException {
        return Objects.equals(x, y);
    }

    @Override
    public int hashCode(HashMap x) throws HibernateException {
        return x == null ? 0 : x.hashCode();
    }

    @Override
    public HashMap nullSafeGet(ResultSet rs, int position,
                               SharedSessionContractImplementor session, Object owner)
        throws HibernateException, SQLException {
        ShogunCoreJsonObjectMapper mapper = new ShogunCoreJsonObjectMapper();
        try {
            String string = rs.getString(position);
            if (string == null) {
                return null;
            }
            HashMap map = mapper.readValue(string, HashMap.class);
            return map;
        } catch (IOException e) {
            throw new HibernateException(e);
        }
    }

    @Override
    public void nullSafeSet(PreparedStatement st, HashMap value, int index,
                            SharedSessionContractImplementor session) throws HibernateException, SQLException {
        if (value == null) {
            st.setNull(index, Types.OTHER);
        } else {
            ShogunCoreJsonObjectMapper mapper = new ShogunCoreJsonObjectMapper();
            try {
                String string = mapper.writeValueAsString(value);
                st.setObject(index, string, Types.OTHER);
            } catch (JsonProcessingException e) {
                throw new HibernateException(e);
            }
        }
    }

    @Override
    public int getSqlType() {
        return Types.OTHER;
    }

}

