@Override
public HashMap assemble(Serializable cached, Object owner) throws HibernateException {
    return cached == null ? null : deepCopy((HashMap) cached);
}

@Override
public HashMap deepCopy(HashMap value) throws HibernateException {
    if (value == null) {
        return null;
    }
    ShogunCoreJsonObjectMapper mapper = new ShogunCoreJsonObjectMapper();
    if (value instanceof String) {
        try {
            return mapper.readValue(value.toString(), HashMap.class);
        } catch (IOException e) {
            throw new HibernateException(e);
        }
    }
    try {
        return mapper.readValue(mapper.writeValueAsString(value), HashMap.class);
    } catch (IOException e) {
        throw new HibernateException(e);
    }
}

@Override
public Serializable disassemble(HashMap value) throws HibernateException {
    return this.deepCopy(value);
}

@Override
public boolean isMutable() {
    return true;
}

@Override
public HashMap replace(HashMap original, HashMap target, Object owner) throws HibernateException {
    return deepCopy(original);
}

