@Test
public void findByCriteria_dealsAsExpectedWithVariousArguments() {
    @SuppressWarnings("unused")
    List<Application> got;
    QueryRestriction<Application> c =
        (root, query, cb) -> cb.equal(root.get("id"), 1);

    got = appDao.findByCriteria();
    assertTrue(true, "findByCriteria() doesn't throw when no argument");

    got = appDao.findByCriteria((QueryRestriction<Application>) null);
    assertTrue(true, "findByCriteria() doesn't throw when null argument");

    got = appDao.findByCriteria(c);
    assertTrue(true, "findByCriteria() doesn't throw when sane argument");

    got = appDao.findByCriteria(c, null);
    assertTrue(true, "findByCriteria() doesn't throw when arguments mixed");
}

/**
 * Tests whether findByCriteria() returns correct results when fed with a
 * simple {@link QueryRestriction}.
 */
@Test
public void findByCriteria_canHandleSimpleCriteria() {
    Application app1 = getRandomSavedMockApp();
    Application app2 = getRandomSavedMockApp();
    QueryRestriction<Application> c1 =
        (root, query, cb) -> cb.equal(root.get("name"), app1.getName());

    List<Application> got = appDao.findByCriteria(c1);

    assertTrue(got.size() == 1, "findByCriteria() returned expected number of apps");
    assertEquals(app1, got.get(0), "findByCriteria() returned expected application");
    assertNotEquals(app2, got.get(0), "findByCriteria() returned expected application");
}

/**
 * Tests whether findByCriteria() returns correct results when fed with a
 * rather complex {@link QueryRestriction}.
 */
@Test
public void findByCriteria_canHandleComplexCriteria() {

    Application app1;
    Application app2;
    Application app3;

    try {
        app1 = getRandomSavedMockApp(); // should be returned
        Thread.sleep(1);
        app2 = getRandomSavedMockApp(); // should not be returned
        Thread.sleep(1);
        app3 = getRandomSavedMockApp(); // should be returned
    } catch (InterruptedException e) {
        fail("Caught exception while attempting to wait");
        return;
    }

    QueryRestriction<Application> or =
        (root, query, cb) -> cb.or(
            cb.equal(root.get("name"), app1.getName()),
            cb.equal(root.get("modified"), app3.getModified())
        );

    List<Application> got = appDao.findByCriteria(or);

    assertTrue(got.size() == 2, "findByCriteria() returned expected number of apps");
    assertTrue(got.contains(app1), "findByCriteria() returned expected applications (app1)");
    assertFalse(got.contains(app2), "findByCriteria() returned expected applications (app2)");
    assertTrue(got.contains(app3), "findByCriteria() returned expected applications (app3)");
}

