/**
 * Helper method: Creates a criteria query for the {@link #entityClass} of
 * this dao. The query results will be distinct root entities. The query
 * will contain all passed restrictions.
 *
 * @param restrictions The restrictions to apply
 * @return The query for the restrictions
 */
private CriteriaQuery<E> createDistinctRootEntityCriteriaQuery(QueryRestriction<E>... restrictions) {
    final Session session = getSession();
    final CriteriaBuilder cb = session.getCriteriaBuilder();
    final CriteriaQuery<E> query = cb.createQuery(entityClass);
    final Root<E> root = query.from(entityClass);

    query.select(root).distinct(true);
    applyRestrictions(query, root, cb, null, restrictions);

    return query;
}

