import de.terrestris.shoguncore.model.Application;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.annotation.Rollback;
import org.springframework.test.context.ContextConfiguration;
import org.springframework.test.context.junit.jupiter.SpringExtension;
import org.springframework.transaction.annotation.Transactional;

import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

@Transactional
@Rollback(true)
@ExtendWith(SpringExtension.class)
@ContextConfiguration(locations = {"classpath*:META-INF/spring/test-context-dao.xml"})
public class ScratchRestrictedTest {

    @Autowired
    AppTestDao appDao;

    @Test
    public void restricted_returnsOnlyRequestedFields() {
        Application a1 = new Application("a1", "d1");
        Application a2 = new Application("a2", "d2");
        appDao.saveOrUpdate(a1);
        appDao.saveOrUpdate(a2);

        // restrict to name only
        List<Application> restricted = appDao.findByCriteriaRestricted(
            Arrays.asList("name"));
        assertEquals(2, restricted.size());
        for (Application app : restricted) {
            assertNull(app.getDescription());
        }

        // restrict to name + description
        List<Application> restricted2 = appDao.findByCriteriaRestricted(
            Arrays.asList("name", "description"));
        assertEquals(2, restricted2.size());
        boolean foundDesc = false;
        for (Application app : restricted2) {
            if ("d1".equals(app.getDescription())) {
                foundDesc = true;
            }
        }
        assertEquals(true, foundDesc);

        // null means no restriction: equals findByCriteria
        List<Application> all = appDao.findByCriteriaRestricted(null);
        assertEquals(2, all.size());
        assertEquals("d1", all.get(0).getDescription());

        // with restriction applied
        QueryRestriction<Application> nameIsA1 =
            (root, query, cb) -> cb.equal(root.get("name"), "a1");
        List<Application> restrictedFiltered = appDao.findByCriteriaRestricted(
            Arrays.asList("name"), nameIsA1);
        assertEquals(1, restrictedFiltered.size());
        assertEquals("a1", restrictedFiltered.get(0).getName());
    }
}
